<?php require 'db.php';$message='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$username=trim($_POST['username']??'');$password=$_POST['password']??'';if(!preg_match('/^[a-zA-Z ]{2,}$/',$name)||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[a-zA-Z0-9_]{3,30}$/',$username)||strlen($password)<8){$error='Enter valid details and a password of at least 8 characters.';}else{$stmt=$mysqli->prepare('SELECT id FROM users WHERE email=? OR username=?');$stmt->bind_param('ss',$email,$username);$stmt->execute();$stmt->store_result();if($stmt->num_rows){$error='Email or username already exists.';}else{$hash=password_hash($password,PASSWORD_DEFAULT);$ins=$mysqli->prepare('INSERT INTO users(name,email,username,password_hash) VALUES(?,?,?,?)');$ins->bind_param('ssss',$name,$email,$username,$hash);if($ins->execute())$message='Registration successful.';else$error='Registration could not be completed.';$ins->close();}$stmt->close();}}?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Secure Registration</title></head><body><h1>Secure User Registration</h1><p><?=htmlspecialchars($message)?></p><p><?=htmlspecialchars($error)?></p><form method="post"><label>Name <input name="name" required></label><br><label>Email <input name="email" type="email" required></label><br><label>Username <input name="username" required></label><br><label>Password <input name="password" type="password" minlength="8" required></label><br><button>Register</button></form></body></html>